// alu_scoreboard.sv
// Reference model + checker for ALU operations
class alu_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(alu_scoreboard)

  uvm_analysis_imp #(alu_seq_item, alu_scoreboard) analysis_export;

  // Counters for statistics
  int unsigned pass_count = 0;
  int unsigned fail_count = 0;
  int unsigned total_count = 0;

  function new(string name = "alu_scoreboard", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    analysis_export = new("analysis_export", this);
  endfunction

  // Reference model: compute expected y and flags
  function void compute_expected(
    input  logic [7:0] a, b,
    input  logic [2:0] opcode,
    output logic [7:0] exp_y,
    output logic [3:0] exp_flags
  );
    logic [8:0] y_complete;

    y_complete = 9'b0;
    exp_y      = 8'b0;
    exp_flags  = 4'b0;

    case (opcode)
      3'b000: begin // ADD
        y_complete    = {1'b0, a} + {1'b0, b};
        exp_y         = y_complete[7:0];
        exp_flags[1]  = y_complete[8]; // carry
        exp_flags[3]  = (~a[7] & ~b[7] & exp_y[7]) | (a[7] & b[7] & ~exp_y[7]); // overflow
      end
      3'b001: begin // SUB
        y_complete    = {1'b0, a} + {1'b0, ~b} + 9'b1;
        exp_y         = y_complete[7:0];
        exp_flags[1]  = y_complete[8]; // carry (borrow complement)
        exp_flags[3]  = (a[7] & ~b[7] & ~exp_y[7]) | (~a[7] & b[7] & exp_y[7]); // overflow
      end
      3'b010: begin // AND
        exp_y = a & b;
      end
      3'b011: begin // OR
        exp_y = a | b;
      end
      3'b100: begin // XOR
        exp_y = a ^ b;
      end
      3'b101: begin // NOT
        exp_y = ~a;
      end
      3'b110: begin // SHL
        exp_flags[1] = a[7]; // carry = MSB shifted out
        exp_y = a << 1;
      end
      3'b111: begin // SHR
        exp_flags[1] = a[0]; // carry = LSB shifted out
        exp_y = a >> 1;
      end
    endcase

    // Common flags
    exp_flags[0] = exp_y[7];            // sign flag
    exp_flags[2] = (exp_y == 8'b0);     // zero flag
  endfunction

  function void write(alu_seq_item txn);
    logic [7:0] exp_y;
    logic [3:0] exp_flags;
    string op_name;

    total_count++;
    compute_expected(txn.a, txn.b, txn.opcode, exp_y, exp_flags);

    case (txn.opcode)
      3'b000: op_name = "ADD";
      3'b001: op_name = "SUB";
      3'b010: op_name = "AND";
      3'b011: op_name = "OR";
      3'b100: op_name = "XOR";
      3'b101: op_name = "NOT";
      3'b110: op_name = "SHL";
      3'b111: op_name = "SHR";
    endcase

    if (txn.y !== exp_y || txn.flags !== exp_flags) begin
      fail_count++;
      `uvm_error(get_type_name(),
        $sformatf("MISMATCH [%s] a=0x%02h b=0x%02h | y: got=0x%02h exp=0x%02h | flags: got=0b%04b exp=0b%04b",
                  op_name, txn.a, txn.b, txn.y, exp_y, txn.flags, exp_flags))
    end else begin
      pass_count++;
      `uvm_info(get_type_name(),
        $sformatf("PASS [%s] a=0x%02h b=0x%02h -> y=0x%02h flags=0b%04b",
                  op_name, txn.a, txn.b, txn.y, txn.flags), UVM_HIGH)
    end
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(),
      $sformatf("\n===== SCOREBOARD SUMMARY =====\nTotal: %0d | Pass: %0d | Fail: %0d\n==============================",
                total_count, pass_count, fail_count), UVM_LOW)
    if (fail_count > 0)
      `uvm_error(get_type_name(), $sformatf("%0d tests FAILED", fail_count))
  endfunction
endclass

