// alu_coverage.sv
// Functional coverage subscriber with covergroups
class alu_coverage extends uvm_subscriber #(alu_seq_item);
  `uvm_component_utils(alu_coverage)

  // Transaction fields for sampling
  logic [7:0] a, b, y;
  logic [2:0] opcode;
  logic [3:0] flags;

  covergroup alu_cg;
    option.per_instance = 1;

    // Opcode coverage — every operation must be exercised
    cp_opcode: coverpoint opcode {
      bins add = {3'b000};
      bins sub = {3'b001};
      bins and_op = {3'b010};
      bins or_op  = {3'b011};
      bins xor_op = {3'b100};
      bins not_op = {3'b101};
      bins shl = {3'b110};
      bins shr = {3'b111};
    }

    // Operand A boundary values
    cp_a: coverpoint a {
      bins zero     = {8'h00};
      bins one      = {8'h01};
      bins max_pos  = {8'h7F};
      bins min_neg  = {8'h80};
      bins max_val  = {8'hFF};
      bins low      = {[8'h02:8'h3F]};
      bins mid      = {[8'h40:8'h7E]};
      bins high     = {[8'h81:8'hFE]};
    }

    // Operand B boundary values
    cp_b: coverpoint b {
      bins zero     = {8'h00};
      bins one      = {8'h01};
      bins max_pos  = {8'h7F};
      bins min_neg  = {8'h80};
      bins max_val  = {8'hFF};
      bins low      = {[8'h02:8'h3F]};
      bins mid      = {[8'h40:8'h7E]};
      bins high     = {[8'h81:8'hFE]};
    }

    // Result coverage
    cp_y: coverpoint y {
      bins zero = {8'h00};
      bins max  = {8'hFF};
      bins others = {[8'h01:8'hFE]};
    }

    // Individual flag coverage
    cp_sign_flag: coverpoint flags[0] {
      bins set   = {1'b1};
      bins clear = {1'b0};
    }

    cp_carry_flag: coverpoint flags[1] {
      bins set   = {1'b1};
      bins clear = {1'b0};
    }

    cp_zero_flag: coverpoint flags[2] {
      bins set   = {1'b1};
      bins clear = {1'b0};
    }

    cp_overflow_flag: coverpoint flags[3] {
      bins set   = {1'b1};
      bins clear = {1'b0};
    }

    // Cross coverage: opcode × flags
    cx_opcode_carry: cross cp_opcode, cp_carry_flag;
    cx_opcode_zero:  cross cp_opcode, cp_zero_flag;
    cx_opcode_sign:  cross cp_opcode, cp_sign_flag;
    cx_opcode_ovf:   cross cp_opcode, cp_overflow_flag;

    // Cross coverage: opcode × operand boundaries
    cx_opcode_a: cross cp_opcode, cp_a;
    cx_opcode_b: cross cp_opcode, cp_b;

  endgroup

  function new(string name = "alu_coverage", uvm_component parent = null);
    super.new(name, parent);
    alu_cg = new();
  endfunction

  function void write(alu_seq_item t);
    a      = t.a;
    b      = t.b;
    y      = t.y;
    opcode = t.opcode;
    flags  = t.flags;
    alu_cg.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(),
      $sformatf("Functional Coverage: %.2f%%", alu_cg.get_inst_coverage()), UVM_LOW)
  endfunction
endclass

